{"intent": "Count network-retrieval commands per thread across attempts", "command": "python3 - <<'PY'
import glob,os,re,json,collections
pat=re.compile(r'curl |wget |git clone|raw\.githubusercontent|registry\.npmjs|pypi|/site-packages|site-packages|node_modules|pip download|npm view|npm pack|find / |locate ')
rows=[]
for f in sorted(glob.glob('bundle/*/*/commands.md')):
    aid=os.path.relpath(os.path.dirname(f),'bundle').replace('/--','--').replace('/','-')
    kind=f.split('/')[1]
    out=json.load(open(os.path.join(os.path.dirname(f),'result.json'))).get('outcome')
    main=[]; other=collections.Counter()
    for line in open(f,errors='replace'):
        m=re.match(r'#(\d+) \[([^\]]+)\] (.*)',line)
        if not m: continue
        cmd=m.group(3)
        if pat.search(cmd):
            if m.group(2)=='main': main.append(cmd[:80])
            else: other[m.group(2)]+=1
    if main or other:
        rows.append((kind,out,aid,len(main),dict(other)))
print(f"{'kind':8} {'outcome':10} {'attempt':45} main other")
for r in rows: print(f"{r[0]:8} {str(r[1]):10} {r[2]:45} {r[3]:4} {r[4]}")
print('TOTAL files with hits:',len(rows))
PY"}

